pub fn name_for(state: u8, bound: u8, id: i32) -> Option<&'static str> {
    let entries = entries_for(state, bound)?;
    entries
        .binary_search_by_key(&id, |&(_, protocol_id)| protocol_id)
        .ok()
        .map(|index| entries[index].0)
}

fn entries_for(state: u8, bound: u8) -> Option<&'static [(&'static str, i32)]> {
    match (state, bound) {
        (STATE_HANDSHAKING, BOUND_CLIENTBOUND) => Some(handshaking::clientbound::ENTRIES),
        (STATE_HANDSHAKING, BOUND_SERVERBOUND) => Some(handshaking::serverbound::ENTRIES),
        (STATE_STATUS, BOUND_CLIENTBOUND) => Some(status::clientbound::ENTRIES),
        (STATE_STATUS, BOUND_SERVERBOUND) => Some(status::serverbound::ENTRIES),
        (STATE_LOGIN, BOUND_CLIENTBOUND) => Some(login::clientbound::ENTRIES),
        (STATE_LOGIN, BOUND_SERVERBOUND) => Some(login::serverbound::ENTRIES),
        (STATE_CONFIGURATION, BOUND_CLIENTBOUND) => Some(configuration::clientbound::ENTRIES),
        (STATE_CONFIGURATION, BOUND_SERVERBOUND) => Some(configuration::serverbound::ENTRIES),
        (STATE_PLAY, BOUND_CLIENTBOUND) => Some(play::clientbound::ENTRIES),
        (STATE_PLAY, BOUND_SERVERBOUND) => Some(play::serverbound::ENTRIES),
        _ => None,
    }
}
